/** Tranco 由来コーパス (rank 昇順)。curated との統合は defaultCorpus.ts が行う。 */
export const TRANCO_ENTRIES: readonly CorpusEntry[] = RAW.map((pair) => {
  const i = pair.indexOf(":");
  return {
    name: pair.slice(i + 1),
    tier: "tranco" as const,
    rank: Number(pair.slice(0, i)),
  };
});
